-- PostgreSQL / Render: update only crase retail selling prices and matched product numbers.
-- Includes the 21 zero prices present in the supplied CSV; prices rounded to two decimals.
-- Product numbers belong to the shared product. Other branch prices and stock/costs are untouched.
BEGIN;
SET LOCAL lock_timeout = '15s';
SET LOCAL statement_timeout = '120s';
CREATE TEMP TABLE _crase_target ON COMMIT DROP AS
SELECT id AS branch_id, tenant_id FROM branches WHERE lower(btrim(name)) = 'crase';
DO $guard$
BEGIN
    IF (SELECT count(*) FROM _crase_target) <> 1 THEN
        RAISE EXCEPTION 'Expected exactly one crase branch. Specify branch id and tenant id in _crase_target.';
    END IF;
END
$guard$;
ALTER TABLE products ADD COLUMN IF NOT EXISTS product_number varchar(191);
CREATE TEMP TABLE _crase_source (
    product_number varchar(191) PRIMARY KEY,
    selling_price numeric(12,2) NOT NULL CHECK (selling_price >= 0)
) ON COMMIT DROP;
CREATE TEMP TABLE _crase_codes (
    product_number varchar(191) NOT NULL, barcode text NOT NULL,
    PRIMARY KEY (product_number, barcode)
) ON COMMIT DROP;
CREATE INDEX ON _crase_codes (barcode);
ANALYZE _crase_source;
ANALYZE _crase_codes;
CREATE TEMP TABLE _crase_candidates ON COMMIT DROP AS
SELECT DISTINCT p.id AS product_id, s.product_number
FROM _crase_target t
JOIN branch_products bp ON bp.branch_id=t.branch_id AND bp.tenant_id=t.tenant_id
JOIN products p ON p.id=bp.product_id AND p.tenant_id=t.tenant_id AND p.deleted_at IS NULL
JOIN _crase_source s ON btrim(p.product_number)=s.product_number
UNION
SELECT DISTINCT p.id AS product_id, c.product_number
FROM _crase_target t
JOIN branch_products bp ON bp.branch_id=t.branch_id AND bp.tenant_id=t.tenant_id
JOIN products p ON p.id=bp.product_id AND p.tenant_id=t.tenant_id AND p.deleted_at IS NULL
JOIN product_barcodes pb ON pb.product_id=p.id AND pb.tenant_id=t.tenant_id
JOIN _crase_codes c ON btrim(pb.barcode)=c.barcode;
CREATE TEMP TABLE _crase_matches ON COMMIT DROP AS
SELECT c.product_id, c.product_number, s.selling_price
FROM (
    SELECT *, count(*) OVER (PARTITION BY product_id) AS numbers_per_product,
        count(*) OVER (PARTITION BY product_number) AS products_per_number
    FROM _crase_candidates
) c
JOIN _crase_source s ON s.product_number=c.product_number
WHERE c.numbers_per_product=1 AND c.products_per_number=1;
-- Lock in stable order. No unmatched products or branch links will be created.
SELECT p.id FROM products p JOIN _crase_matches m ON m.product_id=p.id ORDER BY p.id FOR UPDATE OF p;
SELECT bp.id FROM branch_products bp
JOIN _crase_target t ON bp.branch_id=t.branch_id AND bp.tenant_id=t.tenant_id
JOIN _crase_matches m ON m.product_id=bp.product_id ORDER BY bp.id FOR UPDATE OF bp;
CREATE TEMP TABLE _crase_before ON COMMIT DROP AS
SELECT m.*, p.product_number AS previous_product_number, bp.retail_price AS previous_selling_price
FROM _crase_matches m CROSS JOIN _crase_target t
JOIN products p ON p.id=m.product_id AND p.tenant_id=t.tenant_id
JOIN branch_products bp ON bp.product_id=p.id AND bp.branch_id=t.branch_id AND bp.tenant_id=t.tenant_id;
UPDATE products p SET product_number=m.product_number
FROM _crase_matches m, _crase_target t
WHERE p.id=m.product_id AND p.tenant_id=t.tenant_id
    AND p.product_number IS DISTINCT FROM m.product_number;
UPDATE branch_products bp SET retail_price=m.selling_price
FROM _crase_matches m, _crase_target t
WHERE bp.product_id=m.product_id AND bp.branch_id=t.branch_id AND bp.tenant_id=t.tenant_id
    AND bp.retail_price IS DISTINCT FROM m.selling_price;
SELECT (SELECT count(*) FROM _crase_source) AS source_products,
    (SELECT count(*) FROM _crase_matches) AS matched_products,
    (SELECT count(*) FROM _crase_source s WHERE NOT EXISTS
        (SELECT 1 FROM _crase_candidates c WHERE c.product_number=s.product_number)) AS unmatched_products,
    (SELECT count(DISTINCT c.product_number) FROM _crase_candidates c WHERE NOT EXISTS
        (SELECT 1 FROM _crase_matches m WHERE m.product_number=c.product_number)) AS ambiguous_products_skipped,
    (SELECT count(*) FROM _crase_before WHERE previous_product_number IS DISTINCT FROM product_number) AS product_numbers_changed,
    (SELECT count(*) FROM _crase_before WHERE previous_selling_price IS DISTINCT FROM selling_price) AS selling_prices_changed;
-- Save this result if you want the old values for review or rollback.
SELECT product_id, previous_product_number, product_number, previous_selling_price, selling_price
FROM _crase_before ORDER BY product_id;
COMMIT;
